              parts.push(piece);
              endField(takeParts());
            }
            if (c === delim) {
              state = FIELD_START;
            } else {
              endRecord(out);
              line++;
              lineStart = offset + i + 1;
              state = RECORD_START;
            }
          }
          break;

        case QUOTED:
          if (c === QUOTE) {
            parts.push(chunk.slice(segStart, i));
            state = QUOTE_IN_QUOTED;
          } else if (c === CR || c === LF) {
            line++;
            lineStart = offset + i + 1;
          }
          break;

        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // `""`: the second quote starts the next piece, so it is kept as a literal `"`.
            state = QUOTED;
            segStart = i;
          } else if (c === delim) {
            endField(takeParts());
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(takeParts());
            endRecord(out);
            line++;
            lineStart = offset + i + 1;
            state = RECORD_START;
          } else {
            throw new CsvError(
              `Expected a delimiter or line break after the closing quote, found ${JSON.stringify(chunk[i])}`,
              line,
              offset + i - lineStart + 1,
            );
          }
          break;
      }
    }

    if ((state === UNQUOTED || state === QUOTED) && segStart < n) {
      parts.push(chunk.slice(segStart));
    }
    offset += n;
    return out;
  }

  function finish() {
    const out = [];
    switch (state) {
      case QUOTED:
        throw new CsvError('Unclosed quoted field', fieldLine, fieldColumn);
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        endField(takeParts());
        endRecord(out);
        break;
      case FIELD_START:
        // The input ends right after a delimiter, so the empty field starts at the end.
        fieldLine = line;
        fieldColumn = offset - lineStart + 1;
        endField('');
        endRecord(out);
        break;
      case RECORD_START:
        // Empty input, or input ending in a line break: no further record.
        break;
    }
    return out;
  }

  function ensureOpen(method) {
    if (closed) throw new Error(`Cannot call ${method}(): the parser is closed`);
  }

  return {
    write(chunk) {
      ensureOpen('write');
      try {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string, received ${describe(chunk)}`);
        }
        return feed(chunk);
      } catch (error) {
        closed = true;
        throw error;
      }
