function formatField(value, delimiter, where, index) {
  let s;
  if (typeof value === 'string') s = value;
  else if (typeof value === 'number' || typeof value === 'boolean') s = String(value);
  else if (value === null || value === undefined) return '';
  else {
    throw new TypeError(
      `${where}[${index}] must be a string, number, boolean, null or undefined, received ${describe(value)}`,
    );
