const { parse, createParser } = require('../src/csv.js');

// Deterministic PRNG (mulberry32) so property-test failures reproduce.
function createRandom(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomString(random, alphabet, maxLength) {
  const length = Math.floor(random() * (maxLength + 1));
  const out = [];
  for (let k = 0; k < length; k++) out.push(alphabet[Math.floor(random() * alphabet.length)]);
  return out.join('');
}

// Runs fn and reduces the result to something deepEqual can compare,
// so parse() and the streaming parser can be checked against each other,
// errors included.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (error) {
    return {
      error: { name: error.name, message: error.message, line: error.line, column: error.column },
    };
  }
}

function parseInChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

function splitAt(text, positions) {
  const chunks = [];
  let start = 0;
  for (const position of positions) {
    chunks.push(text.slice(start, position));
    start = position;
  }
  chunks.push(text.slice(start));
  return chunks;
}

function randomChunks(random, text, maxChunk) {
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    // Zero-length chunks are allowed on purpose.
    const size = Math.floor(random() * (maxChunk + 1));
    chunks.push(text.slice(start, start + size));
    start += size;
  }
  chunks.push('');
  return chunks;
}

