'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { createParser, CsvError } = require('../src/csv.js');
const { parse, parseInChunks } = require('./helpers.js');

function assertCsvError(fn, line, column, messagePattern) {
  assert.throws(fn, (error) => {
    assert.ok(error instanceof CsvError, `expected CsvError, got ${error && error.name}`);
    assert.deepEqual({ line: error.line, column: error.column }, { line, column });
    if (messagePattern) assert.match(error.message, messagePattern);
    return true;
  });
}

describe('parse: trim option', () => {
  it('is off by default', () => {
    assert.deepEqual(parse(' a , b \t'), [[' a ', ' b \t']]);
    assert.deepEqual(parse(' a , b ', { trim: false }), [[' a ', ' b ']]);
    assert.throws(() => parse(' "a"'.slice(1) + ' '), CsvError);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
  });

  it('throws TypeError for a non-boolean trim', () => {
    for (const trim of [1, 'yes', null, {}]) assert.throws(() => parse('a', { trim }), TypeError);
  });

  it('removes spaces and tabs from both ends of unquoted fields', () => {
    assert.deepEqual(parse(' a ,\tb\t, \t c d \t\n'), [['a', 'b', 'c d']]);
    assert.deepEqual(parse('  ,\t,   \n\t'), [['', '', ''], ['']]);
    assert.deepEqual(parse(' a \r\n b \r c '), [['a'], ['b'], ['c']]);
  });

  it('trims only spaces and tabs', () => {
    assert.deepEqual(parse(' a ,\fb\v'), [[' a ', '\fb\v']]);
  });

  it('keeps quoted content exactly and drops blanks around the quotes', () => {
    assert.deepEqual(parse(' "  a ""b"" \n" \t,\t" c "\t'), [['  a "b" \n', ' c ']]);
    assert.deepEqual(parse('  ""  ,\t""'), [['', '']]);
  });

  it('treats a field with blanks before its opening quote as quoted', () => {
    assert.deepEqual(parse('  "a,b"\n \t"c\nd"'), [['a,b'], ['c\nd']]);
  });

  it('keeps a quote in the middle of an unquoted field ordinary', () => {
    assert.deepEqual(parse(' a"b" , x "y" '), [['a"b"', 'x "y"']]);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" x'), 1, 5, /found "x"/);
    assertCsvError(() => parse('"a" "b"'), 1, 5);
    assertCsvError(() => parse('a\n  "b"\t"'), 2, 8);
  });

  it('reports an unclosed quoted field at its opening quote', () => {
    assertCsvError(() => parse('a\n \t"b', { trim: true }), 2, 3, /Unclosed/);
  });

  it('never trims a delimiter that is a space or tab', () => {
    assert.deepEqual(parse(' a  b ', { trim: true, delimiter: ' ' }), [['', 'a', '', 'b', '']]);
    assert.deepEqual(parse('\ta\t "b" \t', { trim: true, delimiter: '\t' }), [['', 'a', 'b', '']]);
  });

  it('trims header names and detects duplicates after trimming', () => {
    assert.deepEqual(parse(' id , name \n 1 , x ', { trim: true, header: true }), [{ id: '1', name: 'x' }]);
    assertCsvError(() => parse('a, a\n1,2', { trim: true, header: true }), 1, 3, /Duplicate/);
  });

  it('does not make a blank line empty for skipEmptyLines', () => {
    assert.deepEqual(parse(' \n\n\t\n', { trim: true, skipEmptyLines: true }), [[''], ['']]);
  });

  it('ends a trailing blank field at the end of input', () => {
    assert.deepEqual(parse('a, ', { trim: true }), [['a', '']]);
    assert.deepEqual(parse('a,"b" ', { trim: true }), [['a', 'b']]);
  });
});

// Pass options through parse() and every-position splits of the streaming parser.
function withTrim(text, expected, options) {
  assert.deepEqual(parse(text, options), expected);
  for (let p = 0; p <= text.length; p++) {
    assert.deepEqual(parseInChunks([text.slice(0, p), text.slice(p)], options), expected, `split at ${p}`);
  }
}

describe('createParser: trim option', () => {
  const options = { trim: true };

