describe('parse: trim option', () => {
  it('is off by default', () => {
    assert.deepEqual(parse(' a , b \t', { trim: true }), [[' a ', ' b \t']]);
    assert.deepEqual(parse(' a , b ', { trim: false }), [[' a ', ' b ']]);
    assert.throws(() => parse('"a" '), CsvError);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
  });

  it('throws TypeError for a non-boolean trim', () => {
    for (const trim of [1, 'yes', null, {}]) assert.throws(() => parse('a', { trim }), TypeError);
  });

  it('removes spaces and tabs from both ends of unquoted fields', () => {
    assert.deepEqual(parse(' a ,\tb\t, \t c d \t\n', { trim: true }), [['a', 'b', 'c d']]);
    assert.deepEqual(parse('  ,\t,   \n\t', { trim: true }), [['', '', ''], ['']]);
    assert.deepEqual(parse(' a \r\n b \r c ', { trim: true }), [['a'], ['b'], ['c']]);
  });

  it('trims only spaces and tabs', () => {
    assert.deepEqual(parse('\\u00a0a\\u00a0,\\fb\\v'.replace(/\\\\/g, '\\'), { trim: true }), []);
  });

  it('keeps quoted content exactly and drops blanks around the quotes', () => {
    assert.deepEqual(parse(' "  a ""b"" \n" \t,\t" c "\t', { trim: true }), [['  a "b" \n', ' c ']]);
    assert.deepEqual(parse('  ""  ,\t""', { trim: true }), [['', '']]);
  });

  it('treats a field with blanks before its opening quote as quoted', () => {
    assert.deepEqual(parse('  "a,b"\n \t"c\nd"', { trim: true }), [['a,b'], ['c\nd']]);
  });

  it('keeps a quote in the middle of an unquoted field ordinary', () => {
    assert.deepEqual(parse(' a"b" , x "y" ', { trim: true }), [['a"b"', 'x "y"']]);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" x', { trim: true }), 1, 5, /found "x"/);
    assertCsvError(() => parse('"a" "b"', { trim: true }), 1, 5);
    assertCsvError(() => parse('a\n  "b"\t"', { trim: true }), 2, 8);
  });

  it('reports an unclosed quoted field at its opening quote', () => {
    assertCsvError(() => parse('a\n \t"b', { trim: true }), 2, 3, /Unclosed/);
  });

  it('never trims a delimiter that is a space or tab', () => {
    assert.deepEqual(parse(' a  b ', { trim: true, delimiter: ' ' }), [['', 'a', '', 'b', '']]);
    assert.deepEqual(parse('\ta\t "b" \t', { trim: true, delimiter: '\t' }), [['', 'a', 'b', '']]);
  });

  it('trims header names and detects duplicates after trimming', () => {
    assert.deepEqual(parse(' id , name \n 1 , x ', { trim: true, header: true }), [{ id: '1', name: 'x' }]);
    assertCsvError(() => parse('a, a\n1,2', { trim: true, header: true }), 1, 3, /Duplicate/);
  });

  it('does not make a blank line empty for skipEmptyLines', () => {
    assert.deepEqual(parse(' \n\n\t\n', { trim: true, skipEmptyLines: true }), [[''], ['']]);
  });

  it('ends a trailing blank field at the end of input', () => {
    assert.deepEqual(parse('a, ', { trim: true }), [['a', '']]);
    assert.deepEqual(parse('a,"b" ', { trim: true }), [['a', 'b']]);
  });
});

// Pass options through parse() and every-position splits of the streaming parser.
function withTrim(text, expected, options) {
  assert.deepEqual(parse(text, options), expected);
  for (let p = 0; p <= text.length; p++) {
    assert.deepEqual(parseInChunks([text.slice(0, p), text.slice(p)], options), expected, `split at ${p}`);
  }
}

describe('createParser: trim option', () => {
  const options = { trim: true };

  it('trims across chunk boundaries', () => {
    withTrim(' a b \t, "c" \t\r\n\t d\t', [['a b', 'c'], ['d']], options);
    withTrim('  \t  ,  "x"  \t', [['', 'x']], options);
  });

  it('keeps blanks that a later chunk shows to be inside the field', () => {
    const parser = createParser(options);
    assert.deepEqual(parser.write('a  '), []);
    assert.deepEqual(parser.write(' b  '), []);
    assert.deepEqual(parser.write('\n'), [['a   b']]);
    assert.deepEqual(parser.end(), []);
  });
});

describe('parse: comment option', () => {
  it('is off by default', () => {
    assert.deepEqual(parse('#a\n#b,c'), [['#a'], ['#b', 'c']]);
  });

  it('validates the comment option', () => {
    for (const comment of ['', '##', ',', '"', '\r', '\n', '\r\n', '😀', 5, null, true]) {
      assert.throws(() => parse('a', { comment }), TypeError, JSON.stringify(comment));
    }
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.throws(() => parse('', { comment: '"' }), TypeError);
    assert.doesNotThrow(() => parse('a', { comment: undefined }));
    assert.doesNotThrow(() => parse('a', { comment: '#', delimiter: ';' }));
  });

  it('skips lines starting with the comment character, with their line break', () => {
    const options = { comment: '#' };
    assert.deepEqual(parse('#one\na,b\n# two\r\nc\r#three\rd', options), [['a', 'b'], ['c'], ['d']]);
    assert.deepEqual(parse('#a\n#b\n', options), []);
    assert.deepEqual(parse('a\n#b', options), [['a']]);
    assert.deepEqual(parse('#', options), []);
  });

  it('is not an empty line and never becomes a record', () => {
    assert.deepEqual(parse('a\n#\nb', { comment: '#' }), [['a'], ['b']]);
    assert.deepEqual(parse('a\n#x\n\nb', { comment: '#' }), [['a'], [''], ['b']]);
    assert.deepEqual(parse('#x\n', { comment: '#', header: true }), []);
  });

  it('treats the character as ordinary anywhere else', () => {
    const options = { comment: '#' };
    assert.deepEqual(parse('a#,b#\n c,#d\n"#e"', options), [['a#', 'b#'], [' c', '#d'], ['#e']]);
    assert.deepEqual(parse('\n#x', options), [['']]);
    assert.deepEqual(parse(' #x\n', options), [[' #x']]);
    assert.deepEqual(parse(' #x\n', { comment: '#', trim: true }), [['#x']]);
  });

  it('does not treat a line inside a quoted field as a line start', () => {
    assert.deepEqual(parse('"a\n#b",c\n#d\ne', { comment: '#' }), [['a\n#b', 'c'], ['e']]);
  });

  it('skips comment lines before the header', () => {
    assert.deepEqual(parse('#c\nid\n#c\n1', { comment: '#', header: true }), [{ id: '1' }]);
  });

  it('works with skipEmptyLines and a custom delimiter', () => {
    assert.deepEqual(parse('\n#x;y\na;#b\n\n', { comment: '#', delimiter: ';', skipEmptyLines: true }), [['a', '#b']]);
  });

  it('still counts comment lines in error positions', () => {
    const options = { comment: '#' };
    assertCsvError(() => parse('#a\r\n#b\r#c\na,"b"x', options), 4, 6);
    assertCsvError(() => parse('#a\n#b\n"never', options), 3, 1, /Unclosed/);
    assertCsvError(() => parse('id,id\n', { ...options, header: true }), 1, 4);
    assertCsvError(() => parse('#a\nid,n\n#b\n1', { ...options, header: true }), 4, 1);
  });

  it('counts columns after a BOM and lets the comment start right after it', () => {
    assert.deepEqual(parse('﻿#x\na', { comment: '#' }), [['a']]);
  });
});

describe('createParser: comment option', () => {
  const options = { comment: '#' };

  it('skips comments split anywhere, including inside CRLF', () => {
    const text = '#a\r\nb\r\n#c\r#d\n\n#e';
    const expected = [['b'], ['']];
    assert.deepEqual(parse(text, options), expected);
    for (let p = 0; p <= text.length; p++) {
      assert.deepEqual(parseInChunks([text.slice(0, p), text.slice(p)], options), expected, `split at ${p}`);
    }
    assert.deepEqual(parseInChunks(text.split(''), options), expected);
  });

  it('returns nothing while inside a comment', () => {
    const parser = createParser(options);
    assert.deepEqual(parser.write('a\n#comm'), [['a']]);
    assert.deepEqual(parser.write('ent'), []);
    assert.deepEqual(parser.write('\r'), []);
    assert.deepEqual(parser.write('\nb'), []);
    assert.deepEqual(parser.end(), [['b']]);
  });

  it('throws TypeError for a bad comment', () => {
    assert.throws(() => createParser({ comment: '' }), TypeError);
    assert.throws(() => createParser({ comment: ',' }), TypeError);
    assert.throws(() => createParser({ trim: 'x' }), TypeError);
  });
});

